/**
 * @description
 */

cc.Class({
    extends: cc.Component,
    properties: {
        items: [cc.Node],

        _endCallback: null,
        _canSelect: false,
        _multIndex: -1,
        _timesIndex: -1,
        _freeTime: 0,
    },

    async startSelectFreeTimes() {
        return new Promise((success)=>{
            this.node.active = true;

            this.reset();

            this._canSelect = true;

            this._endCallback = success;

            // let timeOptions = [8, 10, 12, 15, 16, 20, 24, 30];

            this.setAutoPlay();
            for (let i = 0; i < this.items.length; i++) {
                let item = this.items[i];
                item.off(cc.Node.EventType.TOUCH_END);
                item.on(cc.Node.EventType.TOUCH_END, async ()=>{
                    this.clickItemfunc(i);
                });
            }
        })
    },

    setAutoPlay() {
        let list = [];
        for (let i = 0; i < this.items.length; i++){
            if (i !== this._multIndex - 1) {
                list.push(i);
            }
        }
        let randomIdx = Global.random(0,list.length-1);
        let self = this;
        cc.vv.gameData.checkAutoPlay(this.items[list[randomIdx]],  function (){self.clickItemfunc(list[randomIdx])});
    },

    async clickItemfunc(i){
        this.items[i].stopAllActions();

        if (!this._canSelect) {
            return;
        }

        if (i === this._multIndex - 1) {
            return;
        }
        this._canSelect = false;
        Global.SlotsSoundMgr.playEffect("gemopen");

        let timeOptions = [8, 10, 12, 15, 16, 20, 24, 30];

        let req = {rtype:4, choiceId: (i + 1)};
        let result = await cc.vv.gameData.reqSubGame(req);
        if (result.code === 200) {
            let selectItem = this.items[result.data.choiceId - 1];
            let option = result.data.freeOptionGame.items[result.data.choiceId - 1];
            let spine = cc.find("spine", selectItem).getComponent(sp.Skeleton);
            spine.setAnimation(0, "zuanshi_click", false);
            let bgSpine = cc.find("bg", selectItem).getComponent(sp.Skeleton);
            bgSpine.node.active = true;
            bgSpine.setAnimation(0, "di_intro", false);
            bgSpine.addAnimation(0, "di_idle", true);

            await cc.vv.gameData.awaitTime(0.3);
            if (option.mult) {
                this._multIndex = result.data.choiceId;

                let mult = cc.find("mult", selectItem);
                mult.active = true;
                this._canSelect = true;
                this.setAutoPlay();
            } else {
                this._timesIndex = result.data.choiceId;

                let times = cc.find("times", selectItem);
                times.active = true;
                this._freeTime = option.freeCnt;
                let timesIndex = timeOptions.indexOf(option.freeCnt);
                times.getComponent("ImgSwitchCmp").setIndex(timesIndex);

                await cc.vv.gameData.awaitTime(1);

                for (let j = 0; j < this.items.length; j++) {
                    if (!result.data.freeOptionGame.items[j].isOpen) {
                        let notSelectItem = this.items[j];
                        let not_spine = cc.find("spine", notSelectItem).getComponent(sp.Skeleton);
                        not_spine.setAnimation(0, "zuanshi_click", false);
                        let notBgSpine = cc.find("bg", notSelectItem).getComponent(sp.Skeleton);
                        notBgSpine.node.active = true;
                        notBgSpine.setAnimation(0, "di_grey", false);
                        notBgSpine.addAnimation(0, "di_grey_jingzhen", true);

                        cc.tween(notSelectItem)
                            .delay(0.3)
                            .call(()=>{
                                let op = result.data.freeOptionGame.items[j];
                                if (op.mult) {
                                    cc.find("mult", notSelectItem).active = true;
                                } else {
                                    cc.find("times", notSelectItem).active = true;
                                    cc.find("times", notSelectItem).getComponent("ImgSwitchCmp").setIndex(timeOptions.indexOf(op.freeCnt));
                                }
                            })
                            .start();
                    }
                }

                await cc.vv.gameData.awaitTime(1);

                cc.vv.gameData.SetTotalFree(this._freeTime);
                cc.vv.gameData.SetFreeTime(this._freeTime);

                if (this._endCallback) {
                    this._endCallback();
                }
            }
        }
    },

    getFreeTime() {
        return this._freeTime;
    },

    reset() {
        for (let item of this.items) {
            cc.find("spine", item).getComponent(sp.Skeleton).setAnimation(0, "zuanshi_idle", true);
            cc.find("bg", item).active = false;
            cc.find("times", item).active = false;
            cc.find("mult", item).active = false;
        }

        this._multIndex = -1;
        this._timesIndex = -1;
        this._canSelect = false;
        this._endCallback = null;
        this._freeTime = 0;
    },
});