/**
 * @description
 */

cc.Class({
    extends: cc.Component,
    properties: {
        bg: cc.Node,
        pick_bg: cc.Node,
        box_layout: cc.Node,
        wave_tips: cc.Node,
        wave: cc.Node,
        destroy_all_tips: cc.Node,
        gun: cc.Node,
        gun_hurt: cc.Node,
        dialog_node: cc.Node,
        alien_are_comming: cc.Node,
        extra_prize: cc.Node,
        result_node: cc.Node,
        fail_node: cc.Node,
        alien_close: cc.Node,

        _endCallback: null,
        _haveOpenBox: [],
        _canSelect: false,
        _alienBusterGame: null,
        _winCoin: 0,
    },

    startShootGame(alienBusterGame) {
        return new Promise(async (success)=>{
            this.node.active = true;
            this.reset();

            this._alienBusterGame = alienBusterGame;

            this._endCallback = success;

            await this.popAlienAreComming();

            await cc.vv.gameData.awaitTime(1);

            Global.SlotsSoundMgr.playBgm("bgbgm");
            this.registerClickItem();

            this.showAlien(alienBusterGame);
        });
    },

    showAlien(alienBusterGame) {
        this.clearAlien();

        Global.SlotsSoundMgr.playEffect("alienshow");

        if (alienBusterGame.aliens[4].length > 0) {
            this.popAlienClose();
        }

        for (let i = 0; i < alienBusterGame.aliens.length; i++) {
            let aliens = alienBusterGame.aliens[i];
            for (let j = 0; j < aliens.length; j++) {
                let alien = aliens[j];
                let node = cc.instantiate(cc.vv.gameData.GetPrefabByName("alien"));
                node.parent = cc.find("line_" + (i + 1) + "/position_" + (j + 1), this.bg);
                for (let k = 0; k < 7; k++) {
                    cc.find("alien_" + (k + 1), node).active = alien.type === (k + 1);
                }
                let spine = cc.find("alien_" + alien.type, node).getComponent(sp.Skeleton);
                if (i === 0) {
                    spine.setAnimation(0, "intro", false);
                    let alien_intro = cc.find("alien_intro", node);
                    alien_intro.active = true;
                    let alien_intro_spine = alien_intro.getComponent(sp.Skeleton);
                    alien_intro_spine.setAnimation(0, "Alien" + alien.type + "_intro", false);
                    alien_intro_spine.setCompleteListener(()=>{
                        alien_intro_spine.setCompleteListener(null);
                        alien_intro.active = false;
                    });
                } else {
                    spine.setAnimation(0, "intro2", false);
                }
                spine.addAnimation(0, "idle", true);
            }
        }

        for (let i = 0; i < 16; i++) {
            let item = cc.find("item_" + (i + 1), this.box_layout);
            let info = alienBusterGame.items[i];
            let skin = "gun" + info.type;
            if (info.mult > 1) {
                skin += ("_" + info.mult + "x");
            }
            if (info.isOpen) {
                this._haveOpenBox.push(i);
                cc.find("spine", item).getComponent(sp.Skeleton).setSkin(skin);
                cc.find("spine", item).getComponent(sp.Skeleton).setAnimation(0, "result_jingzhen", true);
            } else {
                cc.find("spine", item).getComponent(sp.Skeleton).setAnimation(0, "box_idle", true);
            }
        }

        if (alienBusterGame.round > 10) {
            this.destroy_all_tips.active = true;
            this.wave_tips.active = false;
        } else {
            this.wave_tips.active = true;
            this.wave.getComponent(cc.Label).string = alienBusterGame.round + "/10";
        }


        this._canSelect = true;
        this.setAutoPlay();
    },

    setAutoPlay() {
        let list = [];
        for (let i = 0; i < 16; i++){
            if (this._haveOpenBox.indexOf(i) == -1) {
                list.push(i);
            }
        }

        let randomIdx = Global.random(0,list.length-1);
        let self = this;
        let item = cc.find("item_" + (list[randomIdx]+1), this.box_layout);
        cc.vv.gameData.checkAutoPlay(item,  function (){self.clickItemfunc((list[randomIdx]))});
    },

    async clickItemfunc(i){
        let item = cc.find("item_" + (i + 1), this.box_layout);
        item.stopAllActions();

        if (this._haveOpenBox.indexOf(i) !== -1) {
            return;
        }

        if (!this._canSelect) {
            return;
        }

        Global.SlotsSoundMgr.playEffect("boxopen");
        this._canSelect = false;
        let req = {rtype:5, choiceId: (i + 1)};
        let result = await cc.vv.gameData.reqSubGame(req);
        if (result.code === 200) {
            this.pick_bg.active = false;
            let choiceId = result.data.choiceId;
            let killAliens = result.data.killAliens;
            this._haveOpenBox.push(choiceId - 1);
            this._alienBusterGame = result.data.alienBusterGame;
            for (let i = 0; i < 16; i++) {
                let item = cc.find("item_" + (i + 1), this.box_layout);
                if (this._haveOpenBox.indexOf(i) === -1 && (i + 1) !== choiceId) {
                    cc.find("spine", item).getComponent(sp.Skeleton).setAnimation(0, "box_jingzhen", true);
                }
            }

            let choiceItem = cc.find("item_" + choiceId, this.box_layout);
            let choiceItemSpine = cc.find("spine", choiceItem).getComponent(sp.Skeleton);
            let gunInfo = this._alienBusterGame.items[choiceId - 1];
            let skin = "gun" + gunInfo.type;
            if (gunInfo.mult > 1) {
                skin += ("_" + gunInfo.mult + "x");
            }
            choiceItemSpine.setSkin(skin);
            choiceItemSpine.setAnimation(0, "box_open", false);
            choiceItemSpine.addAnimation(0, "result_jingzhen", true);

            await cc.vv.gameData.awaitTime(1);

            this.gun.active = true;

            let gunSpine = this.gun.getComponent(sp.Skeleton);
            gunSpine.setAnimation(0, "gun" + gunInfo.type, false);
            gunSpine.setCompleteListener(()=>{
                gunSpine.setCompleteListener(null);
                this.gun.active = false;
            });

            if (gunInfo.type === 4) {
                // 一排
                await cc.vv.gameData.awaitTime(0.5);
                Global.SlotsSoundMgr.playEffect("weapon" + gunInfo.type);

                this.gun_hurt.active = true;
                this.gun_hurt.getComponent(sp.Skeleton).setAnimation(0, "gun4", false);
                this.gun_hurt.getComponent(sp.Skeleton).setCompleteListener(()=>{
                    this.gun_hurt.getComponent(sp.Skeleton).setCompleteListener(null);
                    this.gun_hurt.active = false;
                });

                await cc.vv.gameData.awaitTime(1);

                for (let killAlien of killAliens) {
                    let node = this.getAlien(killAlien.lineNo, killAlien.type);
                    let alien = cc.find("alien_" + killAlien.type, node);
                    alien.getComponent(sp.Skeleton).setAnimation(0, "die", false);

                    let coin = cc.find("coin", alien);
                    coin.active = true;
                    coin.getComponent(cc.Label).string = Global.formatNumShort(killAlien.coin, 0);

                    let alien_die = cc.find("alien_die", node);
                    alien_die.active = true;
                    let alien_die_spine = alien_die.getComponent(sp.Skeleton);
                    alien_die_spine.setAnimation(0, "Alien" + killAlien.type + "_die", false);
                    alien_die_spine.setCompleteListener(()=>{
                        alien_die_spine.setCompleteListener(null);
                        alien_die.active = false;
                    })
                }
            } else {
                await cc.vv.gameData.awaitTime(0.5);
                Global.SlotsSoundMgr.playEffect("weapon" + gunInfo.type);

                killAliens.sort((a, b)=>{
                    return a.lineNo - b.lineNo;
                });

                for (let j = 0; j < killAliens.length; j++) {
                    let killAlien = killAliens[j];
                    let node = this.getAlien(killAlien.lineNo, killAlien.type);
                    let alien = cc.find("alien_" + killAlien.type, node);

                    let gun_hurt = cc.find("gun_hurt", alien);
                    gun_hurt.active = true;
                    gun_hurt.getComponent(sp.Skeleton).setAnimation(0, "gun" + gunInfo.type, false);

                    await cc.vv.gameData.awaitTime(0.2);

                    alien.getComponent(sp.Skeleton).setAnimation(0, "die", false);

                    let coin = cc.find("coin", alien);
                    coin.active = true;
                    coin.getComponent(cc.Label).string = Global.formatNumShort(killAlien.coin, 0);

                    Global.SlotsSoundMgr.playEffect("aliendie");
                    let alien_die = cc.find("alien_die", node);
                    alien_die.active = true;
                    let alien_die_spine = alien_die.getComponent(sp.Skeleton);
                    alien_die_spine.setAnimation(0, "Alien" + killAlien.type + "_die", false);
                    alien_die_spine.setCompleteListener(()=>{
                        alien_die_spine.setCompleteListener(null);
                        alien_die.active = false;
                    });

                    await cc.vv.gameData.awaitTime(0.1);
                }
            }

            // 判断结果
            if (this._alienBusterGame.superWinCoin) {
                await this.popExtraPrize();
            }

            if (this._alienBusterGame.isEnd) {
                let leftAliens = false;
                for (let alien of this._alienBusterGame.aliens) {
                    if (alien.length > 0) {
                        leftAliens = true;
                        break;
                    }
                }
                if (leftAliens) {
                    await this.popFail();
                }

                await this.popResultDialog();

                if (this._endCallback) {
                    this._endCallback();
                }
            } else {
                await cc.vv.gameData.awaitTime(2);

                this.showAlien(this._alienBusterGame);
            }
        }
    },

    registerClickItem() {
        this.setAutoPlay();
        for (let i = 0; i < 16; i++) {
            let item = cc.find("item_" + (i + 1), this.box_layout);
            item.off(cc.Node.EventType.TOUCH_END);
            item.on(cc.Node.EventType.TOUCH_END, async ()=>{
                this.clickItemfunc(i);
            });
        }
    },

    getAlien(lineIndex, type) {
        let line = cc.find("line_" + lineIndex, this.bg);
        for (let i = 0; i < 7; i++) {
            let position = cc.find("position_" + (i + 1), line);
            for (let child of position.children) {
                if (cc.find("alien_" + type, child).active) {
                    return child;
                }
            }
        }
        return null;
    },

    popAlienAreComming() {
        return new Promise(async (success)=>{
            Global.SlotsSoundMgr.stopBgm();
            Global.SlotsSoundMgr.playEffect("bgin");
            this.dialog_node.active = true;

            this.alien_are_comming.active = true;
            this.alien_are_comming.scale = 0;

            cc.tween(this.alien_are_comming)
                .to(0.5, {scale: 1}, {easing: "backOut"})
                .start();

            await cc.vv.gameData.awaitTime(0.5);

            let self = this;
            let func = function(){
                Global.SlotsSoundMgr.playEffect("button");
                btn_start.off("click");

                cc.tween(self.alien_are_comming)
                    .to(0.5, {scale: 0}, {easing: "backIn"})
                    .call(() => {
                        self.dialog_node.active = false;
                        self.alien_are_comming.active = false;
                        success();
                    })
                    .start();
            }
            let btn_start = cc.find("btn_start", this.alien_are_comming);
            cc.vv.gameData.checkAutoPlay(btn_start, func);
            btn_start.off("click");
            btn_start.on("click", async () => {
                btn_start.stopAllActions();
                func();
            });
        });
    },

    popAlienClose() {
        return new Promise(async (success)=>{
            Global.SlotsSoundMgr.playEffect("warning");
            this.dialog_node.active = true;

            this.alien_close.active = true;
            this.alien_close.scale = 0;

            cc.tween(this.alien_close)
                .to(0.5, {scale: 1}, {easing: "backOut"})
                .start();

            await cc.vv.gameData.awaitTime(1);

            cc.tween(this.alien_close)
                .to(0.5, {scale: 0}, {easing: "backIn"})
                .call(() => {
                    this.dialog_node.active = false;
                    this.alien_close.active = false;
                    success();
                })
                .start();
        });
    },

    popFail() {
        return new Promise(async (success)=>{
            Global.SlotsSoundMgr.playEffect("caught");
            this.dialog_node.active = true;

            this.fail_node.active = true;
            this.fail_node.scale = 0;

            cc.tween(this.fail_node)
                .to(0.5, {scale: 1}, {easing: "backOut"})
                .start();

            await cc.vv.gameData.awaitTime(1);

            cc.tween(this.fail_node)
                .to(0.5, {scale: 0}, {easing: "backIn"})
                .call(() => {
                    this.dialog_node.active = false;
                    this.fail_node.active = false;
                    success();
                })
                .start();
        });
    },

    popExtraPrize() {
        return new Promise(async (success)=>{
            Global.SlotsSoundMgr.playEffect("destroyall");
            this.dialog_node.active = true;

            this.extra_prize.active = true;
            this.extra_prize.scale = 0;

            cc.tween(this.extra_prize)
                .to(0.5, {scale: 1}, {easing: "backOut"})
                .start();

            cc.find("bg/coin", this.extra_prize).getComponent(cc.Label).string =
                Global.FormatNumToComma(this._alienBusterGame.superWinCoin);

            await cc.vv.gameData.awaitTime(2);

            cc.tween(this.extra_prize)
                .to(0.5, {scale: 0}, {easing: "backIn"})
                .call(() => {
                    this.dialog_node.active = false;
                    this.extra_prize.active = false;
                    success();
                })
                .start();
        });
    },

    popResultDialog() {
        return new Promise(async (success) => {
            Global.SlotsSoundMgr.stopBgm();
            Global.SlotsSoundMgr.playEffect("bgend");

            this.dialog_node.active = true;

            let dialog = cc.find("result_node", this.dialog_node);
            dialog.active = true;
            dialog.scale = 1;

            let freetanchuang = cc.find("freetanchuang", dialog);
            freetanchuang.scale = 0;
            cc.tween(freetanchuang)
                .to(0.5, {scale: 1}, {easing: "backOut"})
                .start();

            let yifenkuang = cc.find("yifenkuang", freetanchuang);
            cc.find("coin", yifenkuang).getComponent(cc.Label).string =
                Global.FormatNumToComma(this._alienBusterGame.winCoin);
            this._winCoin = this._alienBusterGame.winCoin;

            let btn_collect = cc.find("btn_collect", freetanchuang);

            await cc.vv.gameData.awaitTime(1);

            let self = this;
            let func = function(){
                btn_collect.off("click");
                Global.SlotsSoundMgr.playEffect("button");

                cc.tween(dialog)
                    .to(0.5, {scale: 0}, {easing: "backIn"})
                    .call(() => {
                        self.dialog_node.active = false;
                        dialog.active = false;
                        success();
                    })
                    .start();
            }
            cc.vv.gameData.checkAutoPlay(btn_collect,func);
            btn_collect.off("click");
            btn_collect.on("click", async () => {
                btn_collect.stopAllActions();
                func();
            });
        })
    },

    clearAlien() {
        for (let i = 0; i < 5; i++) {
            let line = cc.find("line_" + (i + 1), this.bg);
            for (let j = 0; j < 7; j++) {
                let position = cc.find("position_" + (j + 1), line);
                position.removeAllChildren();
            }
        }
    },

    getWinCoin() {
        return this._winCoin;
    },

    reset() {
        this.clearAlien();
        this.pick_bg.active = true;
        for (let i = 0; i < 16; i++) {
            let item = cc.find("item_" + (i + 1), this.box_layout);
            cc.find("spine", item).getComponent(sp.Skeleton).setAnimation(0, "box_jingzhen", true);
        }
        this.wave_tips.active = true;
        this.wave.getComponent(cc.Label).string = "1/10";
        this.destroy_all_tips.active = false;
        this.gun.active = false;
        this.dialog_node.active = false;

        this._endCallback = null;
        this._alienBusterGame = null;
        this._haveOpenBox = [];
        this._winCoin = 0;
    },
});