    //显示游戏界面：bFree true显示免费模式的界面，false 普通模式
    ShowGameview: function (bFree) {
        this._super(bFree);

        cc.find("reels_frame", this.node).active = !bFree;
        cc.find("reels_frame_free", this.node).active = bFree;
        cc.find("reels_frame_free_2", this.node).active = bFree;
    },

    GetSymbolByIdx: function (idx) {
        let col = (idx - 1) % this._col //考虑到变行，所以行可能有变化
        let row = this._gameInfo.resultCards.length / this._col - Math.floor((idx - 1) / this._col) - 1
        return this._reels[col].GetSymbolByRow(row)
    },

    async collectSymbol() {
        if (this._gameInfo.bonusGame.progressData.currCnt === 0) {
            return;
        }

        let man = cc.find("collect_node/collect", this.node);
        let haveCollect = false;
        for (let i = 0; i < this._gameInfo.resultCards.length; i++) {
            let card = this._gameInfo.resultCards[i];
            if (this._cfg.collectSymbolIds.indexOf(card) !== -1) {
                let symbol = this.GetSymbolByIdx(i + 1);
                if (symbol) {
                    if (cc.vv.gameData.isInFreeGame() && (i / this._cfg.col < (this._gameInfo.minRow - 1))) {
                        continue;
                    }
                    haveCollect = true;
                    let particle = cc.instantiate(cc.find("particle_fly", this.node.parent));
                    particle.active = true;
                    particle.parent = this.node.parent;
                    let startPos = symbol.node.convertToWorldSpaceAR(cc.v2(0, 0));
                    startPos = this.node.parent.convertToNodeSpaceAR(startPos);
                    particle.position = startPos;
                    let endPos = man.convertToWorldSpaceAR(cc.v2(0, 0));
                    endPos = this.node.parent.convertToNodeSpaceAR(endPos);
                    cc.tween(particle)
                        .to(0.5, {position: endPos})
                        .removeSelf()
                        .start();
                }
            }
        }

        if (this._gameInfo.randGame && this._cfg.collectSymbolIds.includes(this._gameInfo.randGame.convertCard)) {
            let array = this._gameInfo.randGame.convertIdxs.concat(this._gameInfo.randGame.convertIdxs2);
            for (let arrayElement of array) {
                let symbol = this.GetSymbolByIdx(arrayElement);
                if (symbol) {
                    haveCollect = true;
                    let particle = cc.instantiate(cc.find("particle_fly", this.node.parent));
                    particle.active = true;
                    particle.parent = this.node.parent;
                    let startPos = symbol.node.convertToWorldSpaceAR(cc.v2(0, 0));
                    startPos = this.node.parent.convertToNodeSpaceAR(startPos);
                    particle.position = startPos;
                    let endPos = man.convertToWorldSpaceAR(cc.v2(0, 0));
                    endPos = this.node.parent.convertToNodeSpaceAR(endPos);
                    cc.tween(particle)
                        .to(0.5, {position: endPos})
                        .removeSelf()
                        .start();
                }
            }
        }

        if (haveCollect) {
            cc.tween(man)
                .delay(0.5)
                .call(() => {
                    Global.SlotsSoundMgr.playEffect("collect");
                    let spine = cc.find("spine", man).getComponent(sp.Skeleton);
                    spine.node.active = true;
                    spine.setAnimation(0, "collect", false);
                    spine.setCompleteListener(() => {
                        spine.setCompleteListener(null);
                        spine.node.active = false;
                    })
                })
                .start();

            await cc.vv.gameData.awaitTime(0.5);

            await this.updateCollectProgress(this._gameInfo.bonusGame, true);
        }
    },

    async triggerFreeGame() {
        this._bottomScript.ShowBtnsByState("moveing_1");

        Global.SlotsSoundMgr.playEffect("triggering");

        for (let i = 0; i < this._gameInfo.resultCards.length; i++) {
            let card = this._gameInfo.resultCards[i];
            if (this._cfg.scatterIds.indexOf(card) !== -1) {
                let symbol = this.GetSymbolByIdx(i + 1);
                symbol.playWinAnimation();
            }
        }

        // 触发免费游戏
        await cc.vv.gameData.awaitTime(2);

        cc.find("node_select_freegames", this.node.parent).active = true;
        let script = cc.find("node_select_freegames", this.node.parent).getComponent("AlienMonster_SelectFreeTimes");
        await script.startSelectFreeTimes();

        await this.popFreeDialog(script.getFreeTime());

        this.cutSceneFreeTime();

        await cc.vv.gameData.awaitTime(1.5);

        for (let reel of this._reels) {
            reel.StartRecycleSymbol(0.1);
        }

        await cc.vv.gameData.awaitTime(0.2);

        this.Backup();
        this.ShowGameview(true);
        for (let reel of this._reels) {
            reel.AddCount(6, 0.01);
        }
        script.node.active = false;

        await cc.vv.gameData.awaitTime(0.5);

        Global.SlotsSoundMgr.stopBgm();
        Global.SlotsSoundMgr.playBgm("fgbgm");
        this.CanDoNextRound();
    },

    async triggerExtraFreeGame() {
        this._bottomScript.ShowBtnsByState("moveing_1");

        Global.SlotsSoundMgr.playEffect("triggering");

        for (let i = 0; i < this._gameInfo.resultCards.length; i++) {
            let card = this._gameInfo.resultCards[i];
            if (this._cfg.scatterIds.indexOf(card) !== -1) {
                let symbol = this.GetSymbolByIdx(i + 1);
                symbol.playWinAnimation();
            }
        }

        await cc.vv.gameData.awaitTime(2);

        await this.popExtraFreeDialog();

        this.CanDoNextRound();
    },

    async triggerExitFreeGame() {
        this._bottomScript.ShowBtnsByState("moveing_1");

        await cc.vv.gameData.awaitTime(1);

        await this.popFreeResultDialog();

        this.cutSceneFreeTime();

        await cc.vv.gameData.awaitTime(1.5);

        this.Resume();
        this.ShowGameview(false);

        for (let reel of this._reels) {
            reel.StartRecycleSymbol(0.01);
        }

        await cc.vv.gameData.awaitTime(1);

        this.ShowBottomWin(cc.vv.gameData.GetGameTotalFreeWin(), cc.vv.gameData.GetGameTotalFreeWin(), true, () => {
            Global.SlotsSoundMgr.stopBgm();
            Global.SlotsSoundMgr.playNormalBgm();
            this.CanDoNextRound();
        });
    },

