    async updateCollectProgress(bonusGame, isAdd) {
        let progress = cc.find("collect_node/progress/mask/bar", this.node);
        if (isAdd) {
            let lizi = cc.find("collect", progress);
            lizi.active = true;
            lizi.getComponent(sp.Skeleton).setAnimation(0, "collect", false);
            lizi.getComponent(sp.Skeleton).setCompleteListener(() => {
                lizi.getComponent(sp.Skeleton).setCompleteListener(null);
                lizi.active = false;
            })

            cc.tween(progress)
                .to(0.3, {
                    x: 368 * (bonusGame.progressData.totalCnt / bonusGame.progressData.needCnt > 1 ?
                        1 : bonusGame.progressData.totalCnt / bonusGame.progressData.needCnt) - 184
                })
                .start();

        } else {
            progress.x = 368 * (bonusGame.progressData.totalCnt / bonusGame.progressData.needCnt > 1 ?
                1 : bonusGame.progressData.totalCnt / bonusGame.progressData.needCnt) - 184
        }
    },

    clearCollectProgress() {
        let progress = cc.find("collect_node/progress/mask/bar", this.node);
        progress.x = -184;
    },
