/**
 * @description
 */

cc.Class({
    extends: cc.Component,
    properties: {
        wheel_node: cc.Node,
        wheel: cc.Node,
        spine_spin: sp.Skeleton,
        spine_win: sp.Skeleton,
        btn_spin: cc.Node,

        _successCallback: null,
        _bonusGame: null,
        _winCoin: 0,
        _index: -1,
    },

    async startWheel(bonusGame) {
        return new Promise((success)=>{
            Global.SlotsSoundMgr.playEffect("wheelshow");
            this.node.active = true;
            this.wheel_node.scale = 0;
            this._successCallback = success;

            cc.tween(this.wheel_node)
                .to(0.5, {scale: 1}, {easing: "backOut"})
                .start();

            this.wheel.angle = 0;

            this.spine_win.node.active = false;

            let func = async ()=>{
                this.btn_spin.off("click");
                Global.SlotsSoundMgr.playEffect("spin");

                let req = {rtype:1};
                let result = await cc.vv.gameData.reqSubGame(req);
                if (result.code === 200) {
                    this._bonusGame = result.data.bonusGame;
                    cc.vv.gameData.getDeskInfo().bonusGame = result.data.bonusGame;
                    this._winCoin = result.data.coin;
                    this._index = result.data.idx;
                    this.spine_spin.setAnimation(0, "click", false);
                    this.spine_spin.addAnimation(0, "jingzhen", true);

                    await this._rotateWheel(result.data.id - 1);

                    this.spine_win.node.active = true;

                    await cc.vv.gameData.awaitTime(1);

                    if (this._successCallback) {
                        this._successCallback();
                    }
                }
            }
            cc.vv.gameData.checkAutoPlay(this.btn_spin, func);
            this.btn_spin.off("click");
            this.btn_spin.on("click", async ()=>{
                this.btn_spin.stopAllActions();
                func();
            });


            for (let i = 0; i < bonusGame.progressData.wheelItems.length; i++) {
                let info = bonusGame.progressData.wheelItems[i];
                cc.find("index_" + (i + 1), this.wheel).getComponent(cc.Label).string = Global.formatNumShort(info.coin, 2);
            }
        });

    },

    getBonusGame() {
        return this._bonusGame;
    },

    getIndex() {
        return this._index;
    },

    getWinCoin() {
        return this._winCoin;
    },

    async _rotateWheel(endIndex) {
        return new Promise((success)=>{
            let angle = endIndex * 60 - 2160;
            cc.log(angle);
            Global.SlotsSoundMgr.playEffect("wheelspin");
            let action = cc.rotateBy(6, angle).easing(cc.easeSineInOut());
            this.wheel.runAction(cc.sequence(action, cc.callFunc(()=>{
                Global.SlotsSoundMgr.playEffect("wheelwin");
                success();
            })));
        });
    },
});