/**
 * @description
 */

cc.Class({
    extends: require("LMSlots_Reel_Base"),

    properties: {

    },

    //旋转
    StartMove:function(){
        this._super();
        if (!cc.vv.gameData.isInFreeGame()) {
            this.StartRecycleSymbol();
        }
    },

    changeAllSymbolToWild() {
        for (let symbol of this._symbols) {
            if (this._cfg.wildIds.indexOf(symbol.GetShowId()) === -1 &&
                this._cfg.scatterIds.indexOf(symbol.GetShowId()) === -1 &&
                this._cfg.shootGameIds.indexOf(symbol.GetShowId()) === -1 &&
                this._cfg.dogWilds.indexOf(symbol.GetShowId()) === -1) {
                symbol.changeToWild();
            }
        }
    },

    ShowAntiEffect:function(bShow,name){
        if (bShow == false) {
            if (this._cfg.reelStateInfo) {
                for (let info of this._cfg.reelStateInfo) {
                    let node = cc.find(info.antiNode,this.node)
                    if(node && node.active){
                        node.active = false
                        // 既然不是循环的播放，就不需要主动停止
                        // 点立即停止的时候需要停止加速音效
                        if(this._stopRightNow){
                            cc.vv.AudioManager.stopEffectByName(info.antSound);
                        }

                    }
                }
            }
        }else{
            let node = cc.find(name,this.node)
            if(node){
                node.active = bShow
                let spine = node.getComponent(sp.Skeleton);
                if (cc.vv.gameData.isInFreeGame()) {
                    spine.setAnimation(0,
                        "tingpai_" + (5 + (7 - cc.vv.gameData.getGameInfo().minRow)),
                        true);
                } else {
                    spine.setAnimation(0,
                        "tingpai_" + (cc.vv.gameData.getGameInfo().resultCards.length / cc.vv.gameData.getGameCfg().col),
                        true);
                }

            }
            else{
                cc.log("未找到加速节点：mask/node_anti");
            }
        }
    },

    //reel变化尺寸的时候，需要移动的节点
    //reels_frame/reel*/frame 
    GetResizeMoveingObjs:function(){
        let objs = []

        if (this._reelIdx === 0) {
            let top = cc.find("reels_frame/top", this.node.parent.parent);
            if (top) {
                objs.push(top);
            }

            // let frameLineUpL = cc.find("reels_frame/frameLineUpL", this.node.parent.parent);
            // if (frameLineUpL) {
            //     objs.push(frameLineUpL);
            // }
            //
            // let frameLineUpR = cc.find("reels_frame/frameLineUpR", this.node.parent.parent);
            // if (frameLineUpR) {
            //     objs.push(frameLineUpR);
            // }

            let collect_node = cc.find("collect_node", this.node.parent.parent);
            if (collect_node) {
                objs.push(collect_node);
            }
        }

        return objs
    },

    //高度变化通知
    //如果自己还有需要根据卷轴变化来处理逻辑
    OnReelHeigtChange:function(nAddHeight){
        if(this._reelIdx == 0){
            let frame = cc.find("reels_frame/frame", this.node.parent.parent);
            frame.height += nAddHeight;
            let line_1 = cc.find("reels_frame/line_1", this.node.parent.parent);
            let line_2 = cc.find("reels_frame/line_2", this.node.parent.parent);
            let line_3 = cc.find("reels_frame/line_3", this.node.parent.parent);
            let line_4 = cc.find("reels_frame/line_4", this.node.parent.parent);
            line_1.height += nAddHeight;
            line_2.height += nAddHeight;
            line_3.height += nAddHeight;
            line_4.height += nAddHeight;
        }
    },

    haveDogAndHide() {
        if (this._originResult) {
            for (let i = 0; i < this._originResult.length; i++) {
                if ((this._originResult[i].sid === 121 || this._originResult[i].sid === 122 || this._originResult[i].sid === 123 || this._originResult[i].sid === 124) && i > 4) {
                    return true;
                }
            }
        }
        return false;
    },

    //reel变化尺寸的时候，需要设置高度的节点(y锚点都是0，这样设置长度都是y方向)
    //reel/mask ,
    //reels_bg/bg*,
    GetResizeHeightObjs:function(){
        let objs = []
        let mask = cc.find("mask",this.node)
        if(mask){
            objs.push(mask)
        }

        let bg = cc.find("reels_bg/reel_bg"+(this._reelIdx+1),this.node.parent.parent)
        if(bg){
            objs.push(bg)
        }

        if (this._reelIdx === 0) {
            for (let i = 0; i < 4; i++) {
                let line = cc.find("reesl_frame/line_" + (i + 1), this.node.parent.parent);
                if (line) {
                    objs.push(line);
                }
            }

            let top_ani = cc.find("top_ani",this.node.parent.parent)
            if(top_ani){
                objs.push(top_ani)
            }
        }

        return objs
    },

    getSymbolNum() {
        return this._nCount;
    },

    //列停止
    OnReelSpinEnd:function(){
        this._super();
    },

    playReelStop(){
        this._super();

        if (this._originResult) {
            for(let i = 0; i < this._originResult.length; i++){
                let item = this._symbols[i]
                if (this._cfg.jackpotIds.includes(item.GetShowId())) {
                    item.playStopAnimation();
                    Global.SlotsSoundMgr.playEffect("reelsctr");
                }
            }
        }
    },


});