/**
 * @description
 */

let JackpotGameSymbol = {
    None: 0,
    Mini: 1,
    Minor: 2,
    Major: 3,
    Mega: 4,
    Grand: 5,
    Gold: 6
};

let animationName = ["mini", "minor", "major", "grand"];
let multIndexs = [2, 3, 4, 5, 10, 25];
let prizePoolName = ["prizePool_Mini", "prizePool_Minor", "prizePool_Major", "prizePool_Grand"];

cc.Class({
    extends: cc.Component,
    properties: {
        layout: cc.Node,
        select_board: cc.Node,
        fly_mult: cc.Node,
        prizePool: cc.Node,

        _successCallback: null,
        _canSelect: false,
        _haveOpenReward: null,
        _jackpotNum: null,
        _jackpotGame: null,
    },

    async startPick(jackpotGame) {
        return new Promise((success)=>{
            Global.SlotsSoundMgr.stopBgm();
            Global.SlotsSoundMgr.playBgm("fgbgm");
            this.node.active = true;
            this.reset();
            this._jackpotGame = jackpotGame;
            this._successCallback = success;
            cc.find("LMSlots_PrizePool_1", this.node).getComponent("LMSlots_PrizePool_Base").PausePool([
                {prizeType: 0, pauseNum: jackpotGame.jackpotValues[0]},
                {prizeType: 1, pauseNum: jackpotGame.jackpotValues[1]},
                {prizeType: 2, pauseNum: jackpotGame.jackpotValues[2]},
                {prizeType: 3, pauseNum: jackpotGame.jackpotValues[3]}
            ]);

            this._canSelect = true;

            this.setAutoPlay();
            for (let i = 1; i < 13; i++) {
                let item = cc.find("item_" + i, this.layout);
                let info = jackpotGame.items[i - 1];
                let spine = cc.find("spine", item).getComponent(sp.Skeleton);
                let jackpot_spine = cc.find("jackpot_spine", item).getComponent(sp.Skeleton);
                if (info.isOpen) {
                    this._haveOpenReward.push(i);
                    let animation = animationName[info.jackpotId - 1]
                    spine.node.active = false;
                    jackpot_spine.node.active = true;
                    jackpot_spine.setAnimation(0, animation + "_di_idle", true);

                    this._jackpotNum[info.jackpotId - 1]++;
                    let ball = cc.find(animation + "/reward_" + this._jackpotNum[info.jackpotId - 1] + "/ball", this.select_board);
                    ball.active = true;
                    ball.getComponent(sp.Skeleton).setAnimation(0, "ball_tx", false);
                    ball.getComponent(sp.Skeleton).addAnimation(0, "ball_" + animation + "_idle", true);

                    if (info.mult > 1) {
                        let mult_node = cc.find("mult_node", item);
                        mult_node.active = true;
                        cc.find("jackpot", mult_node).getComponent("ImgSwitchCmp").setIndex(info.jackpotId - 1);
                        cc.find("mult", mult_node).getComponent("ImgSwitchCmp").setIndex(multIndexs.indexOf(info.mult));

                        let prizePool = cc.find("LMSlots_PrizePool_1/" + prizePoolName[info.jackpotId - 1], this.node);
                        cc.find("mult", prizePool).active = true;
                        cc.find("mult", prizePool).getComponent("ImgSwitchCmp").setIndex(multIndexs.indexOf(info.mult));
                        cc.find("glow", prizePool).active = true;
                    } else {
                        let jackpot = cc.find("jackpot", item);
                        jackpot.active = true;
                        jackpot.getComponent("ImgSwitchCmp").setIndex(info.jackpotId - 1);
                    }
                } else {
                    spine.node.active = true;
                    spine.setAnimation(0, "zuanshi_idle", true);
                }

                item.on(cc.Node.EventType.TOUCH_END, async ()=>{
                    this.clickItemfunc(i);
                });
            }
        });

    },

    setAutoPlay() {
        let list = [];
        for (let i = 1; i < 13; i++){
            if (this._haveOpenReward.indexOf(i) == -1) {
                list.push(i);
            }
        }

        let randomIdx = Global.random(0,list.length-1);
        let self = this;
        let item = cc.find("item_" + list[randomIdx], this.layout);
        cc.vv.gameData.checkAutoPlay(item,  function (){self.clickItemfunc(list[randomIdx])});
    },

    async clickItemfunc(i){
        let item = cc.find("item_" + i, this.layout);
        item.stopAllActions();

        if (!this._canSelect) {
            return;
        }

        if (this._haveOpenReward.indexOf(i) !== -1) {
            return;
        }

        this._canSelect = false;
        Global.SlotsSoundMgr.playEffect("gemopen");
        let req = {rtype:3, choiceId: i};
        let result = await cc.vv.gameData.reqSubGame(req);
        if (result.code === 200) {
            let newJp = result.data.jackpotGame;
            this._jackpotGame = newJp;
            let choiceId = result.data.choiceId;
            let newInfo = newJp.items[choiceId - 1];
            this._haveOpenReward.push(choiceId);

            let selectItem = cc.find("item_" + choiceId, this.layout);
            let spine = cc.find("spine", selectItem).getComponent(sp.Skeleton);
            let jackpot_spine = cc.find("jackpot_spine", selectItem).getComponent(sp.Skeleton);
            let animation = animationName[newInfo.jackpotId - 1]
            spine.setAnimation(0, "zuanshi_clik", false);
            spine.setCompleteListener(()=>{
                spine.setCompleteListener(null);
                spine.node.active = false;
            })
            jackpot_spine.node.active = true;
            jackpot_spine.setAnimation(0, animation + "_di_intro", false);
            jackpot_spine.addAnimation(0, animation + "_di_idle", true);

            if (newInfo.mult > 1) {
                let selectMultNode = cc.find("mult_node", selectItem);
                selectMultNode.active = true;
                cc.find("jackpot", selectMultNode).getComponent("ImgSwitchCmp").setIndex(newInfo.jackpotId - 1);
                cc.find("mult", selectMultNode).getComponent("ImgSwitchCmp").setIndex(multIndexs.indexOf(newInfo.mult));
                selectMultNode.scale = 0;
                cc.tween(selectMultNode)
                    .delay(0.5)
                    .call(()=>{
                        // 圆点
                        this._jackpotNum[newInfo.jackpotId - 1]++;
                        if (!newJp.isEnd) {
                            Global.SlotsSoundMgr.playEffect("jpcount");
                            let ball = cc.find(animation + "/reward_" + this._jackpotNum[newInfo.jackpotId - 1] + "/ball", this.select_board);
                            ball.active = true;
                            ball.getComponent(sp.Skeleton).setAnimation(0, "ball_tx", false);
                            ball.getComponent(sp.Skeleton).addAnimation(0, "ball_" + animation + "_idle", true);
                        } else {
                            Global.SlotsSoundMgr.playEffect("jpmatch");
                            for (let j = 0; j < 3; j++) {
                                let ball = cc.find(animation + "/reward_" + (j + 1) + "/ball", this.select_board);
                                ball.active = true;
                                ball.getComponent(sp.Skeleton).setAnimation(0, "ball_tx", false);
                                ball.getComponent(sp.Skeleton).addAnimation(0, "ball_" + animation + "_idle", true);
                            }
                        }
                    })
                    .to(0.5, {scale: 1}, {easing: "backOut"})
                    .call(()=>{
                        cc.find(prizePoolName[newInfo.jackpotId - 1] + "/glow", this.prizePool).active = true;
                        Global.SlotsSoundMgr.playEffect("jpmulti");
                        let startPos = selectItem.convertToWorldSpaceAR(cc.v2(0, 0));
                        startPos = this.node.convertToNodeSpaceAR(startPos);
                        this.fly_mult.active = true;
                        this.fly_mult.position = startPos;
                        let endPos = cc.find(prizePoolName[newInfo.jackpotId - 1] + "/mult", this.prizePool).convertToWorldSpaceAR(cc.v2(0, 0));
                        endPos = this.node.convertToNodeSpaceAR(endPos);
                        cc.tween(this.fly_mult)
                            .to(0.5, {position: endPos})
                            .call(()=>{
                                this.fly_mult.active = false;
                                cc.find(prizePoolName[newInfo.jackpotId - 1] + "/mult", this.prizePool).active = true;
                                cc.find(prizePoolName[newInfo.jackpotId - 1] + "/mult", this.prizePool).getComponent("ImgSwitchCmp").setIndex(multIndexs.indexOf(newInfo.mult));
                                this._canSelect = !newJp.isEnd;
                                if(this._canSelect){
                                    this.setAutoPlay()
                                }
                            })
                            .start()
                    })
                    .start();
            } else {
                let selectJp = cc.find("jackpot", selectItem);
                selectJp.active = true;
                selectJp.getComponent("ImgSwitchCmp").setIndex(newInfo.jackpotId - 1);
                selectJp.scale = 0;
                cc.tween(selectJp)
                    .delay(0.5)
                    .call(()=>{
                        // 圆点
                        this._jackpotNum[newInfo.jackpotId - 1]++;
                        if (!newJp.isEnd) {
                            Global.SlotsSoundMgr.playEffect("jpcount");
                            let ball = cc.find(animation + "/reward_" + this._jackpotNum[newInfo.jackpotId - 1] + "/ball", this.select_board);
                            ball.active = true;
                            ball.getComponent(sp.Skeleton).setAnimation(0, "ball_tx", false);
                            ball.getComponent(sp.Skeleton).addAnimation(0, "ball_" + animation + "_idle", true);
                        } else {
                            Global.SlotsSoundMgr.playEffect("jpmatch");
                            for (let j = 0; j < 3; j++) {
                                let ball = cc.find(animation + "/reward_" + (j + 1) + "/ball", this.select_board);
                                ball.active = true;
                                ball.getComponent(sp.Skeleton).setAnimation(0, "ball_tx", false);
                                ball.getComponent(sp.Skeleton).addAnimation(0, "ball_" + animation + "_idle", true);
                            }
                        }

                    })
                    .to(0.5, {scale: 1}, {easing: "backOut"})
                    .call(()=>{
                        this._canSelect = !newJp.isEnd;
                        if(this._canSelect){
                            this.setAutoPlay()
                        }
                    })
                    .start();
            }

            if (newJp.isEnd) {
                await cc.vv.gameData.awaitTime(2);

                // Global.SlotsSoundMgr.playEffect("koiSure");
                this.endGame(newJp, choiceId);
            }
        }
    },

    async endGame(jackpotGame, lastChoiceId) {
        for (let j = 1; j < 13; j++) {
            // 所有的翻过来
            let info = jackpotGame.items[j - 1];
            let item = cc.find("item_" + j, this.layout);
            let spine = cc.find("spine", item).getComponent(sp.Skeleton);
            let jackpot_spine = cc.find("jackpot_spine", item).getComponent(sp.Skeleton);
            let animation = animationName[info.jackpotId - 1];
            if (!info.isOpen) {
                spine.setAnimation(0, "zuanshi_clik", false);
                spine.setCompleteListener(()=>{
                    spine.setCompleteListener(null);
                    spine.node.active = false;
                })
                jackpot_spine.node.active = true;
                jackpot_spine.setAnimation(0, animation + "_di_grey_jingzhen", true);

                cc.tween(item)
                    .delay(0.3)
                    .call(()=>{
                        if (info.mult > 1) {
                            let mult_node = cc.find("mult_node", item);
                            mult_node.active = true;
                            cc.find("jackpot", mult_node).getComponent("ImgSwitchCmp").setIndex(info.jackpotId - 1);
                            cc.find("mult", mult_node).getComponent("ImgSwitchCmp").setIndex(multIndexs.indexOf(info.mult));

                            let prizePool = cc.find("LMSlots_PrizePool_1/" + prizePoolName[info.jackpotId - 1], this.node);
                            cc.find("mult", prizePool).active = true;
                            cc.find("mult", prizePool).getComponent("ImgSwitchCmp").setIndex(multIndexs.indexOf(info.mult));
                            cc.find("glow", prizePool).active = true;
                        } else {
                            let jackpot = cc.find("jackpot", item);
                            jackpot.active = true;
                            jackpot.getComponent("ImgSwitchCmp").setIndex(info.jackpotId - 1);
                        }
                    })
                    .start();
            }
        }

        await cc.vv.gameData.awaitTime(1);

        if (this._successCallback) {
            this._successCallback();
        }
    },

    getJackpotGame() {
        return this._jackpotGame;
    },

    reset() {
        // 重置所有金币节点
        for (let i = 1; i < 13; i++) {
            let item = cc.find("item_" + i, this.layout);
            let spine = cc.find("spine", item).getComponent(sp.Skeleton);
            spine.node.active = true;
            spine.setAnimation(0, "zuanshi_idle", true);

            cc.find("jackpot_spine", item).active = false;

            cc.find("jackpot", item).active = false;
            cc.find("mult_node", item).active = false;
        }

        for (let i = 0; i < animationName.length; i++) {
            let jp = cc.find(animationName[i], this.select_board);
            for (let j = 0; j < 3; j++) {
                cc.find("reward_" + (j + 1) + "/ball", jp).active = false;
            }
        }

        for (let child of cc.find("LMSlots_PrizePool_1", this.node).children) {
            cc.find("mult", child).active = false;
            cc.find("glow", child).active = false;
        }

        // 重置变量
        this._successCallback = null;
        this._canSelect = false;
        this._haveOpenReward = [];
        this._jackpotNum = [0, 0, 0, 0];
        this._jackpotGame = null;
    },
});